#include <iostream>
#include <string>
#include "../include/url_parser.h"

int main(int argc, char* argv[]) {
    if (argc < 2) return 1;

    std::string url = argv[1];
    url_parser::URL parser(url);

    // Test all getters
    std::cout << parser.scheme() << std::endl;
    std::cout << parser.authority() << std::endl;
    std::cout << parser.userinfo() << std::endl;
    std::cout << parser.host() << std::endl;
    std::cout << parser.port() << std::endl;
    std::cout << parser.path() << std::endl;
    std::cout << parser.query() << std::endl;
    std::cout << parser.fragment() << std::endl;

    // Test all has_* methods
    std::cout << parser.has_scheme() << std::endl;
    std::cout << parser.has_authority() << std::endl;
    std::cout << parser.has_userinfo() << std::endl;
    std::cout << parser.has_host() << std::endl;
    std::cout << parser.has_port() << std::endl;
    std::cout << parser.has_path() << std::endl;
    std::cout << parser.has_query() << std::endl;
    std::cout << parser.has_fragment() << std::endl;

    // Test to_string and is_valid
    std::cout << parser.to_string() << std::endl;
    std::cout << parser.is_valid() << std::endl;

    return 0;
}


